arguments.command:
cd /workspace/repo && python -c "
from textkit.pairs import parse_pairs, ParseError
print('1. parse_pairs(\"a=1;oops\") ->', end=' ')
try:
    parse_pairs('a=1;oops')
except ParseError as e:
    print(f'ParseError({e})')
print('2. parse_pairs(\"=1\") ->', end=' ')
try:
    parse_pairs('=1')
except ParseError as e:
    print(f'ParseError({e})')
print('3. parse_pairs(\"expr=x=1\") ->', parse_pairs('expr=x=1'))
print('4. empty key whitespace: parse_pairs(\"  = 2\") ->', end=' ')
try:
    parse_pairs('  = 2')
except ParseError as e:
    print(f'ParseError({e})')
"

